program.compute:
pool = read('/input/options')
if goal['order_by']:
    pool = sorted(pool, key=lambda row: [row[field] for field in goal['order_by']])
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
selection = None
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        selection = existing
if selection is None and result is not None:
    selection = result
    write('/output/selection', selection)
if selection is not None and status('report') == 'not_sent':
    send("report", "team", selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

